// @name Slow movie
// A film played very slowly: one still every few minutes, each a few seconds
// of film after the last, so a whole movie takes days or weeks to go by. Made
// for e-paper, where a still is all the panel shows anyway. The film is a
// video file in the frame's assets (the first one in videos/ unless the
// settings name one); where it is is kept on disk, and at the end it starts
// again. Needs a Raspberry Pi to read the film (docs/video.md).
const VIDEO = /\.(mp4|m4v|mov|mkv|webm|avi|ts|mpg|mpeg|wmv|ogv)$/i

let durations = {} // file -> seconds, read once

const clock = (s) => {
  const h = Math.floor(s / 3600)
  const m = String(Math.floor((s % 3600) / 60)).padStart(2, '0')
  return `${h}:${m}:${String(Math.floor(s % 60)).padStart(2, '0')}`
}

function filmOf(app) {
  const named = String(app.state.file ?? '').trim()
  if (named) return named
  // Named from the assets' top: "videos/film.mp4".
  const found = (frameos.listAssets('videos') || []).filter((name) => VIDEO.test(name)).sort()
  return found.length ? found[0] : ''
}

// What the scene needs, said where it can be read on any panel: the note 14 px
// at the least, wrapped in a column 70 % of the width and centred (so inside
// the circle on a round one).
function Message({ title, text, k, width }) {
  return (
    <div className="w-full h-full flex flex-col items-center justify-center bg-white text-black gap-[8px]">
      <span className={`w-[${Math.round(width * 0.8)}px] text-[${Math.max(18, Math.round(24 * k))}px] font-bold text-center`}>{title}</span>
      <span className={`w-[${Math.round(width * 0.7)}px] text-[${Math.max(14, Math.round(16 * k))}px] text-center`}>{text}</span>
    </div>
  )
}

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(2, Math.min(width / 800, height / 480)))
  const film = filmOf(app)
  if (!film) {
    return <Message k={k} width={width} title="Slow movie" text="Copy a film into the frame's assets folder, in videos/, or name one in the scene's settings." />
  }
  if (!(film in durations)) {
    const info = frameos.videoInfo(film)
    if (info.error) return <Message k={k} width={width} title="Slow movie" text={`${film}: ${info.error}`} />
    durations[film] = info.duration ?? 0
  }
  const duration = durations[film]
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch {}
  }
  if (!spot || typeof spot !== 'object') spot = {}
  let at = spot.film === film ? Number(spot.at) || 0 : Number(app.state.start) || 0
  if (duration > 0 && at >= duration - 0.5) at = 0
  // The still is decoded at the panel's own pixels, whatever the UI's scale.
  const scale = Math.max(1, Number(app.frame.scale) || 1)
  const still = frameos.videoFrame(film, {
    at,
    width: Math.round(width * scale),
    height: Math.round(height * scale),
    fit: app.state.fit === 'contain' ? 'contain' : 'cover',
  })
  if (!still.image) {
    // Past what the file holds (a duration it did not say): from the start.
    frameos.setState('spot', { film, at: 0 })
    return <Message k={k} width={width} title="Slow movie" text={`${film}: ${still.error ?? 'no picture there'}`} />
  }
  // The next still, a step further on.
  const step = Math.max(0.04, Number(app.state.step) || 4)
  frameos.setState('spot', { film, at: duration > 0 && at + step >= duration ? 0 : at + step })
  const name = film.split('/').pop().replace(VIDEO, '')
  return (
    <div className="relative w-full h-full bg-black">
      <img className="w-full h-full" src={still.image} />
      {app.state.caption !== false ? (
        <div className={`absolute right-[${Math.round(10 * k)}px] bottom-[${Math.round(8 * k)}px] px-[8px] py-[2px] bg-white`}>
          <span className={`text-[${Math.round(13 * k)}px] text-black`}>
            {`${name} · ${clock(at)}${duration > 0 ? ` of ${clock(duration)}` : ''}`}
          </span>
        </div>
      ) : null}
    </div>
  )
}
